/**
 * Model b_users
 * 前台业务系统用户，是知识库、文档上传和聊天会话的归属主体。
 */
export type b_users = $Result.DefaultSelection<Prisma.$b_usersPayload>
/**
 * Model b_user_sessions
 * 前台用户登录会话，用于 Refresh Token 轮换、注销和过期控制。
 */
export type b_user_sessions = $Result.DefaultSelection<Prisma.$b_user_sessionsPayload>
/**
 * Model sys_email_codes
 * 邮箱验证码，支持注册、密码重置等认证场景。
 */
export type sys_email_codes = $Result.DefaultSelection<Prisma.$sys_email_codesPayload>
/**
 * Model sys_admins
 * 后台管理系统用户，支持超级管理员和运营人员等角色。
 */
export type sys_admins = $Result.DefaultSelection<Prisma.$sys_adminsPayload>
/**
 * Model sys_admin_sessions
 * 后台管理员登录会话。
 */
export type sys_admin_sessions = $Result.DefaultSelection<Prisma.$sys_admin_sessionsPayload>
/**
 * Model sys_model_configs
 * 系统级模型配置，密钥从环境变量读取，不保存到数据库。
 */
export type sys_model_configs = $Result.DefaultSelection<Prisma.$sys_model_configsPayload>
/**
 * Model b_user_model_configs
 * 用户自定义模型配置，API Key 以 AES-256-GCM 密文保存。
 */
export type b_user_model_configs = $Result.DefaultSelection<Prisma.$b_user_model_configsPayload>
/**
 * Model b_knowledge_bases
 * 知识库主体，关联所有者、成员、邀请、文档和上传会话。
 */
export type b_knowledge_bases = $Result.DefaultSelection<Prisma.$b_knowledge_basesPayload>
/**
 * Model b_kb_members
 * 知识库与用户的多对多成员关系，并保存成员角色。
 */
export type b_kb_members = $Result.DefaultSelection<Prisma.$b_kb_membersPayload>
/**
 * Model b_kb_invitations
 * 知识库邀请记录，邀请码默认只能使用一次。
 */
export type b_kb_invitations = $Result.DefaultSelection<Prisma.$b_kb_invitationsPayload>
/**
 * Model b_documents
 * 文档元数据，文件内容保存在外部文件存储中。
 */
export type b_documents = $Result.DefaultSelection<Prisma.$b_documentsPayload>
/**
 * Model b_upload_sessions
 * MinIO Multipart Upload 上传会话。该表只记录传输过程，不记录文档处理任务。
 */
export type b_upload_sessions = $Result.DefaultSelection<Prisma.$b_upload_sessionsPayload>
/**
 * Model b_upload_parts
 * MinIO Multipart Upload 中的单个文件分片。
 */
export type b_upload_parts = $Result.DefaultSelection<Prisma.$b_upload_partsPayload>
/**
 * Model b_document_chunks
 * 文档某次 processing run 生成的文本切片。
 * 每个批次使用一个不可变 embedding 配置；vector_id 在批次指定的 Qdrant 目标内定位。
 */
export type b_document_chunks = $Result.DefaultSelection<Prisma.$b_document_chunksPayload>
/**
 * Model b_document_processing_runs
 * 一次上传处理或重新向量化处理批次。
 * 该表不表示用户可见的文件版本。
 */
export type b_document_processing_runs = $Result.DefaultSelection<Prisma.$b_document_processing_runsPayload>
/**
 * Model b_document_processing_tasks
 * 文档处理批次中的具体任务，同时保存 BullMQ Job 映射。
 * BullMQ 的队列状态保存在 Redis；本表保存业务状态和长期执行快照。
 */
export type b_document_processing_tasks = $Result.DefaultSelection<Prisma.$b_document_processing_tasksPayload>
/**
 * Model b_chat_sessions
 * 用户聊天会话，保存最近使用的知识库和聊天模式。
 */
export type b_chat_sessions = $Result.DefaultSelection<Prisma.$b_chat_sessionsPayload>
/**
 * Model b_chat_messages
 * 聊天消息，保存用户输入、助手回答及流式响应状态。
 */
export type b_chat_messages = $Result.DefaultSelection<Prisma.$b_chat_messagesPayload>
/**
 * Model b_chat_message_citations
 * 消息引用记录，将回答与知识库、文档和文本块关联起来。
 */
export type b_chat_message_citations = $Result.DefaultSelection<Prisma.$b_chat_message_citationsPayload>
/**
 * Model b_outbox_events
 * 与业务变更在同一 MySQL 事务中创建；投递和消费采用至少一次语义。
 * 不关联业务外键，确保业务行被删除后清理清单仍可执行；过期归档需独立策略。
 */
export type b_outbox_events = $Result.DefaultSelection<Prisma.$b_outbox_eventsPayload>

